import csv
from collections import defaultdict

data = defaultdict(list)
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        data[r['timeseries_id']].append((r['timestamp'], float(r['value'])))
for d in data.values(): d.sort()

ids = {}
with open(CATALOG_CSV) as f:
    for r in csv.DictReader(f):
        if r['point_class']=='Zone_Air_Temperature_Sensor':
            z = r['point_uri'].split('#')[-1].replace('.Zone_Air_Temperature_Sensor','')
            ids[z] = r['timeseries_id']

def monthly_mean(sid):
    m = defaultdict(list)
    for ts,v in data[sid]:
        m[ts[:7]].append(v)
    return {mo: sum(vals)/len(vals) for mo,vals in m.items()}

zones = ['Zone_F3_Z01','Zone_F3_Z02','Zone_F3_Z03','Zone_F3_Z05','Zone_F2_Z01','Zone_F4_Z01']
res={}
for z in zones:
    mm = monthly_mean(ids[z])
    res[z]=mm
    print(z, {mo: round(v,2) for mo,v in sorted(mm.items())})

# Compare average over months before July (Jan-Jun) vs after (Jul-Dec)
for z in zones:
    mm=res[z]
    before = [mm[m] for m in mm if m<'2018-07']
    after = [mm[m] for m in mm if m>='2018-07']
    print(z, "before", round(sum(before)/len(before),2), "after", round(sum(after)/len(after),2))
